vp.addEventListener('click',e=>{if(!view||view.mode!=='explore'||e.target.tagName!=='CANVAS'||(pointerStart&&Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)>6))return;view.pick?.(e.clientX,e.clientY);renderUI();});vp.addEventListener('pointerdown',e=>{if(e.target.tagName!=='CANVAS'||!view)return;pointerStart={x:e.clientX,y:e.clientY};dragging=true;lastPointer={x:e.clientX,y:e.clientY};e.target.setPointerCapture(e.pointerId);e.target.focus();});vp.addEventListener('pointermove',e=>{if(!dragging||!lastPointer||!view)return;const dx=e.clientX-lastPointer.x,dy=e.clientY-lastPointer.y;if(view.mode==='overview'){view.orbit.yaw-=dx*.008;view.orbit.pitch=Math.max(.15,Math.min(1.5,view.orbit.pitch+dy*.006));}else if(!sim.experience.blocking){sim.player.yaw-=dx*.004;sim.player.pitch=Math.max(-1.2,Math.min(1.2,sim.player.pitch-dy*.004));}lastPointer={x:e.clientX,y:e.clientY};});for(const ev of['pointerup','pointercancel'])vp.addEventListener(ev,()=>{dragging=false;lastPointer=null;});vp.addEventListener('wheel',e=>{if(view?.mode==='overview'){e.preventDefault();view.orbit.distance=Math.max(18,Math.min(145,view.orbit.distance+e.deltaY*.045));}},{passive:false});
