$('#inventory-open').onclick=()=>showItems('browse');$('#item-use-open').onclick=()=>showItems('use');$('#life-close').onclick=()=>{sim.items.cancel();sim.experience.trade=null;renderUI();};
$('#parcel-get').onclick=()=>{sim.message=sim.items.obtain()?'実験用の届け物を受け取りました。':'届け物はすでに受け取っています。';renderUI();};
$('#trade-open').onclick=()=>{const n=sim.experience.nearNPC();if(!n||!sim.life.canTrade(n.id)){sim.message='営業中の店主の近くで取引してください。';return;}sim.experience.trade=n.id;showItems('trade');};
$('#save-life').onclick=()=>{try{saveLocal(sim);sim.message='このブラウザに保存しました。';}catch(e){sim.message=e.message;}renderUI();};
$('#load-life').onclick=()=>{try{loadLocal(sim);keys.clear();routeKey='';makeView();}catch(e){sim.message=e.message;}renderUI();};
$('#hide-npcs').onchange=e=>{if(view)view.hideNPCs=e.target.checked;};
$('#npc-controls').innerHTML=PEOPLE.map(n=>n.name+['home','work','auto'].map((m,i)=>'<button data-npc="'+n.id+'" data-location="'+m+'">'+['自室へ','仕事場へ','自動へ'][i]+'</button>').join('')).join(' ');document.querySelectorAll('[data-location]').forEach(b=>b.onclick=()=>{sim.life.requestLocation(b.dataset.npc,b.dataset.location);renderUI();});
function renderLifeUI(){const e=sim.items;$('#life-clock').textContent='生活時計 '+sim.life.time.toFixed(1)+'秒 / 60秒周期';$('#life-status').textContent=PEOPLE.map(n=>{const r=sim.life.states[n.id];return n.name+'：'+(r.location==='home'?'在室':'勤務')+' '+sim.life.location(n.id).body+' / '+r.stage+(r.location==='work'?' / 次の在室 '+sim.life.nextHome(n.id).toFixed(1)+'秒':'');}).join(' ｜ ');$('#life-panel').hidden=!e.mode;if(!e.mode)return;$('#life-title').textContent=e.mode==='browse'?'所持品を見る':e.mode==='trade'?'営業中の取引':'品物を選び、対象へ使う';const box=$('#life-content'),esc=v=>String(v).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));let html=Object.entries(e.counts).filter(([,q])=>q>0).map(([id,q])=>'<div class="life-item"><b>'+esc(ITEMS[id]?.name??id)+' × '+q+'</b><p>'+esc(ITEMS[id]?.description??'引き継いだ品物')+'</p>'+(e.mode==='use'?'<button data-item="'+esc(id)+'">この品を選ぶ</button>':'')+'</div>').join('')||'<p>所持品はありません。</p>';if(e.mode==='trade')html+='<p>実験の取引：届け物を受取人へ手渡せます。通貨・回収品売却の本編システムは未統合です。</p><button data-hand-over>届け物を渡す</button>';if(e.mode==='use'&&e.selected)html+='<p>選択中：'+esc(ITEMS[e.selected]?.name??e.selected)+'</p>'+PEOPLE.map(n=>'<button data-target="npc:'+n.id+'">'+n.name+'に使う</button><button data-target="door:'+n.home.door+'">'+n.home.door+'に使う</button>').join('');if(e.results.length)html+='<p role="status">'+esc(e.results.at(-1).message)+'</p>';if(box.innerHTML!==html)box.innerHTML=html;box.querySelectorAll?.('[data-item]').forEach(b=>b.onclick=()=>{e.selected=b.dataset.item;renderUI();});box.querySelectorAll?.('[data-target]').forEach(b=>b.onclick=()=>{e.use(e.selected,b.dataset.target);renderUI();});box.querySelector?.('[data-hand-over]')?.addEventListener('click',()=>{e.use('parcel','npc:'+sim.experience.trade);renderUI();},{once:true});}

makeView();renderUI();let last=performance.now();function frame(t){const frameStarted=performance.now(),dt=Math.min(.1,(t-last)/1000);last=t;if(view?.mode==='explore'&&!$('#help').open){const forward=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),side=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0);if(['idle','warning','evacuate'].includes(sim.mode)&&!sim.anyLiftActive){if(!sim.experience.blocking)sim.player.yaw+=(keys.has('ArrowLeft')?1:0)*dt*1.7-(keys.has('ArrowRight')?1:0)*dt*1.7;sim.walk(forward,side,dt,keys.has('ShiftLeft')||keys.has('ShiftRight'));}}sim.tick(dt);audio.update(sim);screenEffects();view?.render();if(t-lastUI>120){renderUI();lastUI=t;}frameProfiler.record(t,performance.now()-frameStarted,sim,view);requestAnimationFrame(frame);}requestAnimationFrame(frame);
window.lab={sim,audio,performance:()=>frameProfiler.report(),get view(){return view;},setView,matrix,measurements,snapshot:()=>({phase:sim.phase,mode:sim.mode,experiment:{...sim.experiment},positions:structuredClone(sim.positions),player:{...sim.player},webgl:!!view})};
